# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"
require_relative "contract_example_helpers"

RSpec.describe TimekeepingSnapshots do
  include TimekeepingContractExampleHelpers

  let(:snapshots_spec_contract) { TimekeepingContract.load(:entry_snapshots) }

  it "builds an entry holding exactly the contract's entry_fields with the shared defaults" do
    entry = described_class.entry(id: 11, company_id: 3, version: 2, project_id: 5, user_id: 7)

    expect(entry.keys).to match_array(snapshots_spec_contract.fetch("entry_fields"))
    expect(entry).to include(
      "id" => 11, "company_id" => 3, "version" => 2, "project_id" => 5, "user_id" => 7,
      "work_date" => "2026-03-02", "duration" => 90.0, "note" => "v2", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "proof_metadata" => {}, "created_at" => "2026-03-02T09:00:00Z", "updated_at" => "2026-03-02T09:00:00Z",
      "agent_id" => nil, "discarded_at" => nil
    )
  end

  it "replaces defaults with symbol-keyed overrides, including nested metadata and falsy values" do
    entry = described_class.entry(
      id: 11, company_id: 3, version: 2, project_id: 5, user_id: 7,
      note: "", duration: 0.0, locked: true, review_status: "approved", source: "cli",
      source_metadata: { "tool" => "codex", "nested" => { "depth" => 2 } },
      updated_at: "2026-03-02T10:00:00+01:00", discarded_at: "2026-03-03T10:00:00Z"
    )

    expect(entry).to include(
      "note" => "", "duration" => 0.0, "locked" => true, "review_status" => "approved", "source" => "cli",
      "source_metadata" => { "tool" => "codex", "nested" => { "depth" => 2 } },
      "updated_at" => "2026-03-02T10:00:00+01:00", "discarded_at" => "2026-03-03T10:00:00Z"
    )
    # A symbol key left beside the string default would send a payload with a key the contract does not list.
    expect(entry.keys).to match_array(snapshots_spec_contract.fetch("entry_fields"))
  end

  # The request spec sends `invoice_id: 7` on purpose to prove the endpoint refuses it, so the builder must pass it through.
  it "still merges an override key outside the contract instead of raising" do
    entry = described_class.entry(id: 93_001, company_id: 2, version: 1, project_id: 4, user_id: 5, invoice_id: 7)

    expect(entry.fetch("invoice_id")).to eq(7)
    expect(entry.keys - snapshots_spec_contract.fetch("entry_fields")).to eq(["invoice_id"])
  end

  # Every spec shares the builder, so a default hash reused between calls would let one example
  # change the payload another example sends.
  it "does not leak a change to one built entry into the next entry" do
    first = described_class.entry(id: 1, company_id: 3, version: 1, project_id: 5, user_id: 7)
    first["source_metadata"]["token"] = "secret"
    first["proof_metadata"]["url"] = "https://example.test"
    first["note"] = "changed"

    second = described_class.entry(id: 1, company_id: 3, version: 1, project_id: 5, user_id: 7)

    expect(second).to include("source_metadata" => {}, "proof_metadata" => {}, "note" => "v1")
  end

  it "wraps an entry in an item with the contract's item_fields and the entry version as outbox_position" do
    entry = described_class.entry(id: 11, company_id: 3, version: 4, project_id: 5, user_id: 7)

    item = described_class.item(entry, generation: 2)
    positioned = described_class.item(entry, generation: 1, outbox_position: 9)

    expect(item.keys).to match_array(snapshots_spec_contract.fetch("item_fields"))
    expect(item).to eq("generation" => 2, "outbox_position" => 4, "entry" => entry)
    expect(positioned).to eq("generation" => 1, "outbox_position" => 9, "entry" => entry)
  end

  # Specs build re-sends and unsorted batches on purpose to test the consumer, so the wrapper
  # must neither drop a duplicate nor reorder items.
  it "wraps items in a batch with the contract's batch_fields and schema_version, exactly as given" do
    newer = described_class.item(described_class.entry(id: 1, company_id: 2, version: 2, project_id: 3, user_id: 4),
                                 generation: 1, outbox_position: 9)
    older = described_class.item(described_class.entry(id: 1, company_id: 2, version: 1, project_id: 3, user_id: 4),
                                 generation: 1, outbox_position: 4)
    schema_version = snapshots_spec_contract.fetch("schema_version")

    batch = described_class.batch(newer, older, newer)

    expect(batch.keys).to match_array(snapshots_spec_contract.fetch("batch_fields"))
    expect(batch).to eq("schema_version" => schema_version, "snapshots" => [newer, older, newer])
    expect(described_class.batch).to eq("schema_version" => schema_version, "snapshots" => [])
  end

  # Explicit generation, project and user keep the timekeeping_arrange defaults from being evaluated.
  it "snapshot_item still returns the exact item it built before delegating, with every default and override in place" do
    item = snapshot_item(entry_id: 80_001, company: 2, version: 3, generation: 4, project: 5, user: 6,
                         discarded_at: "2026-03-03T10:00:00Z")

    expected_entry = snapshots_spec_contract.fetch("entry_fields").index_with(nil).merge(
      "id" => 80_001, "company_id" => 2, "version" => 3, "project_id" => 5, "user_id" => 6,
      "work_date" => "2026-03-02", "duration" => 90.0, "note" => "v3", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "proof_metadata" => {}, "created_at" => "2026-03-02T09:00:00Z", "updated_at" => "2026-03-02T09:00:00Z",
      "discarded_at" => "2026-03-03T10:00:00Z"
    )
    expect(item).to eq("generation" => 4, "outbox_position" => 3, "entry" => expected_entry)
  end

  # Every argument is distinct and explicit, so a swapped id (company for project, user for entry) changes the result.
  it "snapshot_item maps its arguments onto the shared builder without swapping any" do
    item = snapshot_item(entry_id: 101, company: 202, version: 3, generation: 4, outbox_position: 9,
                         project: 505, user: 606, note: "moved", duration: 30.0)

    expected = described_class.item(
      described_class.entry(id: 101, company_id: 202, version: 3, project_id: 505, user_id: 606, note: "moved", duration: 30.0),
      generation: 4, outbox_position: 9
    )
    expect(item).to eq(expected)
    expect(item.fetch("entry").values_at("id", "company_id", "project_id", "user_id")).to eq([101, 202, 505, 606])
  end
end
